CREATE TABLE matching_run (run_id uuid PRIMARY KEY, model_version text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, records_considered integer NOT NULL DEFAULT 0);
CREATE TABLE resident_match_pair (run_id uuid NOT NULL REFERENCES matching_run(run_id), canonical_record_a uuid NOT NULL REFERENCES canonical_resident(canonical_resident_id), canonical_record_b uuid NOT NULL REFERENCES canonical_resident(canonical_resident_id), match_probability numeric NOT NULL, match_weight numeric NOT NULL, decision text NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (run_id, canonical_record_a, canonical_record_b), CHECK (canonical_record_a < canonical_record_b));
